// Get references to DOM elements
const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");
const increaseBtn = document.getElementById("increase");
const decreaseBtn = document.getElementById("decrease");
const sizeEl = document.getElementById("size");
const colorEl = document.getElementById("color");
const clearEl = document.getElementById("clear");

// Initial drawing settings
let size = 10;
let isDrawing = false;
let color = colorEl.value || "black";
let x, y;

// Start drawing on mouse down
canvas.addEventListener("mousedown", (e) => {
  isDrawing = true;
  [x, y] = [e.offsetX, e.offsetY];
});

// Stop drawing on mouse up
document.addEventListener("mouseup", () => {
  isDrawing = false;
  x = y = null;
});

// Draw when the mouse moves
canvas.addEventListener("mousemove", (e) => {
  if (!isDrawing) return;

  const x2 = e.offsetX;
  const y2 = e.offsetY;

  drawCircle(x2, y2);
  drawLine(x, y, x2, y2);

  [x, y] = [x2, y2];
});

/**
 * Draw a filled circle at the given position
 */
function drawCircle(x, y) {
  ctx.beginPath();
  ctx.arc(x, y, size, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
}

/**
 * Draw a line from (x1, y1) to (x2, y2)
 */
function drawLine(x1, y1, x2, y2) {
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.strokeStyle = color;
  ctx.lineWidth = size * 2;
  ctx.stroke();
}

// Increase brush size
increaseBtn.addEventListener("click", () => {
  size = Math.min(size + 5, 50);
  sizeEl.textContent = size;
});

// Decrease brush size
decreaseBtn.addEventListener("click", () => {
  size = Math.max(size - 5, 5);
  sizeEl.textContent = size;
});

// Change brush color
colorEl.addEventListener("change", (e) => {
  color = e.target.value;
});

// Clear canvas
clearEl.addEventListener("click", () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
});

const canvas = document.querySelector("#canvas");
const ctx = canvas.getContext("2d");

// Set canvas size
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const wavePatterns = [];
const numberOfWaves = 25;

// Initialize waves with random properties
for (let i = 0; i < numberOfWaves; i++) {
  wavePatterns.push({
    baseY: canvas.height / 2 - 100 + Math.random() * 200, // Vertical position of the wave
    wavelength: 0.01 + Math.random() * 0.001, // Controls the wave frequency
    amplitude: 50 + Math.random() * 100, // Height of the wave
    speed: 0.01 + Math.random() * 0.03, // Speed of wave movement
    phase: Math.random() * Math.PI * 2, // Initial phase shift
  });
}

function animateWaves() {
  requestAnimationFrame(animateWaves);

  // Create a fading effect for smooth animation
  ctx.fillStyle = `rgba(0, 0, 0, 0.03)`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw each wave
  wavePatterns.forEach((wave, index) => {
    ctx.beginPath();
    ctx.moveTo(0, wave.baseY);

    for (let x = 0; x < canvas.width; x++) {
      const yOffset =
        Math.sin(x * wave.wavelength + wave.phase) *
        wave.amplitude *
        Math.sin(wave.phase);

      ctx.lineTo(x, wave.baseY + yOffset);
    }

    // Set stroke color with a hue variation for a gradient effect
    ctx.strokeStyle = `hsl(${index / 2 + 170}, 100%, 50%)`;
    ctx.stroke();

    // Update wave phase to create movement
    wave.phase += wave.speed;
  });
}

// Start animation
animateWaves();

// Adjust canvas size on window resize and reposition waves
window.addEventListener("resize", () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  wavePatterns.forEach((wave) => {
    wave.baseY = canvas.height / 2 - 100 + Math.random() * 200;
  });
});

