/* Navigation container */
nav {
    background-color: #fff;
    padding: 20px;
    width: 80px; /* Default width when collapsed */
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 3px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
    transition: width 0.6s linear;
    overflow-x: hidden;
}

/* Expanded navigation */
nav.active {
    width: 350px;
}

/* Menu container */
nav .container {
    display: flex;
    list-style-type: none;
    width: 0; /* Hidden by default */
    transition: width 0.6s linear;
}

/* Show container when active */
nav.active .container {
    width: 100%;
}

/* Menu items */
nav .container .item {
    transform: rotateY(0deg);
    opacity: 0;
    transition: transform 0.6s linear, opacity 0.6s linear;
}

/* Rotate links when active */
nav.active .container .item {
    opacity: 1;
    transform: rotateY(360deg);
}

/* Navigation links */
nav .container .nav_link {
    text-decoration: none;
    position: relative;
    color: #000;
    margin: 0 10px;
}

/* Toggle button */
.icon {
    background-color: #fff;
    border: none;
    cursor: pointer;
    position: relative;
    height: 30px;
    width: 30px;
}

/* Remove button outline on focus */
.icon:focus {
    outline: none;
}

/* Menu button lines */
.icon .line {
    background-color: #5290f9;
    height: 2px;
    width: 20px;
    position: absolute;
    top: 10px;
    left: 5px;
    transition: transform 0.6s linear;
}

/* Adjust bottom line position */
.icon .line2 {
    top: auto;
    bottom: 10px;
}

/* Animate menu button to an 'X' */
nav.active .icon .line1 {
    transform: rotate(-765deg) translateY(5.5px);
}

nav.active .icon .line2 {
    transform: rotate(765deg) translateY(-5.5px);
}

