    backgroundColor: { value: new THREE.Vector3(0.1, 0.1, 0.1) }, // Grey background tint
    borderWidth: { value: 0.03 }, // Width of the border
    vignetteAmount: { value: 0.5 } // Strength of the vignette
  },
  vertexShader: `
        varying vec2 vUv;
        void main() {
