@import url("https://fonts.googleapis.com/css?family=Roboto:100,300,400,500,700");
@import url('https://fonts.googleapis.com/css?family=Source+Code+Pro:300,500');

/* 🎨 CSS Variables for easy theming */
:root {
    --background-color: #24272e;
    --primary-color: #fff;
    --highlight-win: #4dcc7d;
    --highlight-loss: #c52e2e;
    --highlight-draw: #444;
    --font-family: "Roboto", sans-serif;
}

html {
    box-sizing: border-box;
}

*, *::before, *::after {
    box-sizing: inherit;
    margin: 0;
    padding: 0;
}

body {
    background: var(--background-color);
    color: var(--primary-color);
    font-family: var(--font-family);
    text-align: center;
    display: block;
    background: linear-gradient(60deg, rgb(175, 107, 107), rgb(98, 172, 85));
}

header {
    background: var(--primary-color);
    padding: 20px;
}

header h1 {
    color: #444;
    font-weight: 100;
}

/* 🎯 Scoreboard */
.score-board {
    border: 3px solid var(--primary-color);
    width: 300px;
    margin: 40px auto;
    font-size: 40px;
    border-radius: 8px;
    padding: 15px;
    position: relative;
    background: rgba(255, 255, 255, 0.1);
}

.badge {
    background: #e2584d;
    font-size: 14px;
    padding: 10px;
    border-radius: 4px;
}

#user-label {
    position: absolute;
    top: 50%;
    left: -10%;
    transform: translateY(-50%);
}

#computer-label {
    position: absolute;
    top: 50%;
    right: -10%;
    transform: translateY(-50%);
}

/* 🎯 Result Display */
.result {
    font-size: 32px;
    font-weight: 300;
    margin: 20px;
    padding: 10px;
